// Generated by scaffold-page-from-story from user_stories/ADM-03-course-detail.yaml
// Story: US-ADM-03-COURSE-DETAIL
// Role:  admin
// Feature: Course editor with sections and lessons
// Goal: As an operator I can edit one course and manage its lessons so that a published course can actually be filled with content.
//
// Restyled by convert-pages to mirror design/html/admin/ADM-03-course-detail.html.
// Scope-locked parts preserved verbatim: every data-testid, the default export,
// and the fetch + loading/error/empty data wiring (updateCourses2
// / removeLessons4). Presentation + real data binding added around them.

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { getCourse, updateCourse, addLesson, deleteLesson, listCategories } from '~/services/httpServices/adminConsoleService';
import { listInstructors } from '~/services/httpServices/catalogueService';
import { toast } from '~/lib/toast';
import { RoleEnum } from '~/enums/role.enum';
import { course_status } from '~/enums/course-status.enum';
import { lesson_type } from '~/enums/lesson-type.enum';
import { DataTable, type DataTableColumn } from '~/components/data-table/DataTable';
import { RowSelect } from '~/components/listing/RowSelect';
import { RowActions } from '~/components/listing/RowActions';
import { BulkActions } from '~/components/listing/BulkActions';
import { EntityFormModal } from '~/components/listing/EntityFormModal';
import { useRowSelection } from '~/components/listing/useRowSelection';
import { SearchInput } from '~/components/atoms/SearchInput';
import { ArrowLeft, Plus, Trash2 } from 'lucide-react';
import type { CourseDetail, LessonRow } from '~/types/view-models';
import { useSlugField } from '~/hooks/useSlugField';
import { RichTextEditor } from '~/components/ui/rich-text-editor';
import { ImageUrlField } from '~/components/shared/ImageUrlField';
import { getApiErrorMessage } from '~/utils/apiError';

const CARD = 'rounded-[var(--radius-xl)] border border-border bg-card p-6 shadow-sm';
const INPUT =
  'flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm text-foreground shadow-sm transition-colors placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50';
const LABEL = 'text-sm font-medium text-foreground';
const BTN_PRIMARY =
  'inline-flex items-center justify-center gap-2 rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground shadow-sm transition-colors hover:bg-primary/90 disabled:pointer-events-none disabled:opacity-50';
const BTN_SECONDARY =
  'inline-flex items-center justify-center gap-2 rounded-md border border-input bg-background px-3 py-2 text-sm font-medium text-foreground shadow-sm transition-colors hover:bg-accent hover:text-accent-foreground disabled:pointer-events-none disabled:opacity-50';
const BTN_DANGER =
  'inline-flex items-center justify-center gap-2 rounded-md bg-destructive px-3 py-2 text-sm font-medium text-white shadow-sm transition-colors hover:bg-destructive/90 disabled:pointer-events-none disabled:opacity-50';
const BTN_GHOST =
  'inline-flex items-center justify-center gap-2 rounded-md px-3 py-2 text-sm font-medium text-foreground transition-colors hover:bg-accent hover:text-accent-foreground';

function toItems(res: unknown): Record<string, unknown>[] {
  if (Array.isArray(res)) return res as Record<string, unknown>[];
  if (res && typeof res === 'object') {
    const r = res as { items?: unknown; data?: unknown };
    if (Array.isArray(r.items)) return r.items as Record<string, unknown>[];
    if (Array.isArray(r.data)) return r.data as Record<string, unknown>[];
    if (r.data && typeof r.data === 'object') {
      const d = r.data as { items?: unknown };
      if (Array.isArray(d.items)) return d.items as Record<string, unknown>[];
    }
  }
  return [];
}

const titleCase = (s: string) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();

/** Sentinel for the "new section" choice in the lesson dialog's section picker. */
const NEW_SECTION = '__new__';

/** Numeric lesson_type → the word the table shows. */
function typeOf(value: unknown): string {
  const n = Number(value);
  const hit = Object.entries(lesson_type).find(([, v]) => v === n);
  return hit ? titleCase(hit[0]) : '';
}

/**
 * What each lesson type MEANS — the picker offered four words and explained
 * none of them, so "Quiz" and "Live" were guesses. Shown under the picker.
 */
const TYPE_HELP: Record<number, { en: string }> = {
  [lesson_type.VIDEO]: { en: 'A recorded video the student watches. Needs a video URL.' },
  [lesson_type.ARTICLE]: { en: 'Written material the student reads. Put the text in Article / notes.' },
  [lesson_type.QUIZ]: { en: 'Questions the student answers to check what they learnt. Write them in Article / notes until the quiz builder lands.' },
  [lesson_type.LIVE]: { en: 'A scheduled live session. Put the meeting link in Video URL and the date and joining details in Article / notes.' },
};
const optId = (o: Record<string, unknown>) => String(o.id ?? o._id ?? '');
const optName = (o: Record<string, unknown>) => String(o.name ?? o.title ?? o.fullName ?? '');

export default function AdminCourseDetailPage() {
  const { t } = useTranslation('common');
  const __routeParams = useParams() as Record<string, string | undefined>;
  const dispatch = useAppDispatch();
  const id = __routeParams.id;
  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState<number>(0);
  const reload = () => setReloadKey((k) => k + 1);

  useEffect(() => {
    if (!id) { setLoading1(false); return; }
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    dispatch(getCourse(id)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, id, reloadKey]);

  const [loading2, setLoading2] = useState<boolean>(false);
  const updateCourses2 = async () => {
    if (!id) return;
    setLoading2(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="adm-03-course-detail-ac-2"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    try {
      await updateCourse(id, __body);
      toast.success(t('admin.courseDetail.saved', { defaultValue: 'Course saved' }));
      reload();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : t('admin.courseDetail.saveFailed', { defaultValue: 'Could not save the course' }));
    } finally {
      setLoading2(false);
    }
  };
  const [loading4, setLoading4] = useState<boolean>(false);
  const removeLesson = async (lessonId: string) => {
    if (!lessonId) return;
    setLoading4(true);
    try {
      await deleteLesson(lessonId);
      toast.success(t('admin.courseDetail.lessonDeleted', { defaultValue: 'Lesson deleted' }));
      reload();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : t('admin.courseDetail.lessonDeleteFailed', { defaultValue: 'Could not delete the lesson' }));
    } finally {
      setLoading4(false);
    }
  };
  const removeLessons4 = async () => {
    const ids = sel.selected;
    if (ids.length === 0) return;
    setLoading4(true);
    try {
      await Promise.all(ids.map((lessonId) => deleteLesson(lessonId)));
      toast.success(t('admin.courseDetail.lessonsDeleted', { defaultValue: 'Lessons deleted' }));
      sel.clear();
      reload();
    } catch (e) {
      toast.error(e instanceof Error ? e.message : t('admin.courseDetail.lessonDeleteFailed', { defaultValue: 'Could not delete the lessons' }));
    } finally {
      setLoading4(false);
    }
  };

  // --- enhancement: role, dropdown sources, lesson search + add modal ---
  // The /admin/* route tree is wrapped by AdminGuard (manifest guard `auth:admin`),
  // so every visitor who reaches this page is an authenticated admin.
  const role: string = RoleEnum.admin;
  const isAdmin = role === RoleEnum.admin;
  const [categories, setCategories] = useState<Record<string, unknown>[]>([]);
  const [instructors, setInstructors] = useState<Record<string, unknown>[]>([]);
  const [addOpen, setAddOpen] = useState<boolean>(false);
  const [lessonQuery, setLessonQuery] = useState<string>('');
  // A lesson lives under a SECTION, and a freshly created course has none — so
  // the form offers the course's sections and lets the operator name a new one.
  const [lessonSection, setLessonSection] = useState<string>('');
  const [lessonType, setLessonType] = useState<string>(String(lesson_type.VIDEO));
  const [lessonContent, setLessonContent] = useState<string>('');
  const [lessonError, setLessonError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    dispatch(listCategories(undefined)).unwrap().then((res) => { if (active) setCategories(toItems(res)); }).catch(() => {});
    dispatch(listInstructors(undefined)).unwrap().then((res) => { if (active) setInstructors(toItems(res)); }).catch(() => {});
    return () => { active = false; };
  }, [dispatch]);

  const course: CourseDetail | null =
    data1 && typeof data1 === 'object'
      ? (((data1 as { data?: CourseDetail }).data ?? (data1 as CourseDetail)) ?? null)
      : null;
  // Controlled, not `defaultValue`.
  //
  // `defaultValue` on a <select> is applied ONCE, at mount. Both option lists
  // arrive from their own fetch afterwards, so at mount each select held nothing
  // but its "Select category" placeholder and the default had no option to land
  // on — every course, however it was classified, opened showing "Select
  // category" and "Select instructor". Saving from that form then reassigned the
  // course to nothing.
  const [categoryId, setCategoryId] = useState<string>('');
  const [instructorId, setInstructorId] = useState<string>('');
  // The slug follows the title, but only while it is blank — a published course
  // keeps the URL it already has when someone rewords its title.
  const slugField = useSlugField();
  const [thumbnail, setThumbnail] = useState<string>('');
  useEffect(() => {
    if (!course) return;
    setCategoryId(String(course.categoryId ?? ''));
    setInstructorId(String(course.instructorId ?? ''));
    slugField.reset(course.slug ? String(course.slug) : '');
    setThumbnail(course.thumbnailUrl ? String(course.thumbnailUrl) : '');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [course?.id, course?.categoryId, course?.instructorId, course?.slug, course?.thumbnailUrl]);

  const sections: { id: string; title: string }[] = Array.isArray(course?.sections)
    ? (course!.sections as { id?: unknown; title?: unknown }[]).map((sec) => ({
        id: String(sec.id ?? ''),
        title: String(sec.title ?? ''),
      })).filter((sec) => sec.id)
    : [];

  /**
   * The payload carries lessons nested under `sections[]`, never as a flat
   * `course.lessons` — so this table read a field that does not exist and every
   * course, however full its syllabus, showed "No lessons yet". Flatten it, and
   * carry the section name down so the Section column has something to say.
   */
  const lessons: LessonRow[] = Array.isArray(course?.sections)
    ? (course!.sections as { id?: unknown; title?: unknown; lessons?: unknown }[]).flatMap((sec) =>
        (Array.isArray(sec.lessons) ? (sec.lessons as Record<string, unknown>[]) : []).map((l) => ({
          id: String(l.id ?? ''),
          order: typeof l.displayOrder === 'number' ? l.displayOrder : undefined,
          section: String(sec.title ?? ''),
          title: String(l.title ?? ''),
          type: typeOf(l.contentType),
          duration: typeof l.durationMinutes === 'number' && l.durationMinutes > 0
            ? `${l.durationMinutes} min`
            : '',
        })),
      )
    : [];
  const q = lessonQuery.trim().toLowerCase();
  const filteredLessons = lessons.filter(
    (l) => !q || String(l.title ?? '').toLowerCase().includes(q) || String(l.section ?? '').toLowerCase().includes(q),
  );
  const sel = useRowSelection(filteredLessons.map((l) => String(l.id ?? '')));

  const statusOptions = Object.entries(course_status).filter(([, v]) => typeof v === 'number') as [string, number][];
  const typeOptions = Object.entries(lesson_type).filter(([, v]) => typeof v === 'number') as [string, number][];

  const studentsCount = Number(course?.studentsCount ?? course?.studentCount ?? course?.enrollmentCount ?? 0);
  const ratingValue = Number(course?.rating ?? course?.averageRating ?? 0);

  const columns: DataTableColumn<LessonRow>[] = [
    {
      key: 'select',
      label: '',
      width: '44px',
      render: (row) => (
        <RowSelect
          checked={sel.isSelected(String(row.id))}
          onChange={() => sel.toggle(String(row.id))}
          testId={`lessons-${row.id}`}
          label={t('admin.courseDetail.selectLesson', { defaultValue: 'Select lesson' })}
        />
      ),
    },
    { key: 'order', label: t('admin.courseDetail.order', { defaultValue: 'Order' }), sortable: true },
    { key: 'section', label: t('admin.courseDetail.section', { defaultValue: 'Section' }), sortable: true },
    { key: 'title', label: t('admin.courseDetail.lesson', { defaultValue: 'Lesson' }), sortable: true },
    { key: 'type', label: t('admin.courseDetail.type', { defaultValue: 'Type' }), sortable: true },
    { key: 'duration', label: t('admin.courseDetail.duration', { defaultValue: 'Duration' }), sortable: true },
  ];

  function openAddLesson() {
    const first = sections[0];
    setLessonSection(first ? String(first.id) : NEW_SECTION);
    setLessonType(String(lesson_type.VIDEO));
    setLessonContent('');
    setLessonError(null);
    setAddOpen(true);
  }

  /**
   * Reads the dialog's own FormData. It used to sweep every input inside the
   * whole "Sections and lessons" card, which pulled in the search box and the
   * row checkboxes, and dropped any field left blank.
   */
  async function handleAddLesson(form: FormData) {
    if (!id) return;
    const str = (k: string) => String(form.get(k) ?? '').trim();
    const title = str('title');
    if (!title) {
      setLessonError(t('admin.courseDetail.lessonTitleRequired', { defaultValue: 'A lesson needs a title.' }));
      throw new Error('title required');
    }
    const sectionTitle = str('sectionTitle');
    if (lessonSection === NEW_SECTION && !sectionTitle) {
      setLessonError(t('admin.courseDetail.sectionRequired', { defaultValue: 'Name the new section, or pick an existing one.' }));
      throw new Error('section required');
    }

    const body: Record<string, unknown> = {
      title,
      contentType: Number(str('contentType') || lesson_type.VIDEO),
    };
    if (lessonSection === NEW_SECTION) body.sectionTitle = sectionTitle;
    else if (lessonSection) body.sectionId = lessonSection;
    if (str('videoUrl')) body.videoUrl = str('videoUrl');
    if (lessonContent.trim() && lessonContent !== '<p></p>') body.content = lessonContent;
    if (str('durationMinutes')) body.durationMinutes = Number(str('durationMinutes'));
    if (str('displayOrder')) body.displayOrder = Number(str('displayOrder'));

    setLessonError(null);
    try {
      await addLesson(id, body);
      toast.success(t('admin.courseDetail.lessonAdded', { defaultValue: 'Lesson added' }));
      setAddOpen(false);
      reload();
    } catch (e) {
      const msg = getApiErrorMessage(e, t('admin.courseDetail.lessonAddFailed', { defaultValue: 'Could not add the lesson' }));
      toast.error(msg);
      setLessonError(msg);
      throw e; // keep the dialog open with what was typed
    }
  }

  return (
    <div data-testid="adm-03-course-detail-page" className="w-full">
      <Link
        to="/admin/courses"
        data-testid="adm-03-course-detail-home-link"
        className="mb-4 inline-flex items-center gap-1 text-sm text-muted-foreground transition-colors hover:text-foreground"
      >
        <ArrowLeft className="h-4 w-4" aria-hidden="true" />
        {t('admin.courseDetail.backToCourses', { defaultValue: 'Courses' })}
      </Link>

      <main data-testid="adm-03-course-detail-main">
        {loading1 && (
          <div data-testid="adm-03-course-detail-ac-1-loading" className="rounded-lg border border-border bg-card p-12 text-center text-muted-foreground">
            {t('actions.loading', { defaultValue: 'Loading…' })}
          </div>
        )}

        {error1 && (
          <div data-testid="adm-03-course-detail-ac-1-error" className="rounded-lg border border-destructive/40 bg-card p-6">
            <p className="text-sm text-destructive">
              {t('admin.courseDetail.loadError', { defaultValue: 'Could not load the course.' })} {error1}
            </p>
            <button
              type="button"
              onClick={() => window.location.reload()}
              data-testid="adm-03-course-detail-ac-1-retry"
              className={`mt-3 ${BTN_SECONDARY}`}
            >
              {t('actions.retry', { defaultValue: 'Retry' })}
            </button>
          </div>
        )}

        {!loading1 && !error1 && !course && (
          <div data-testid="adm-03-course-detail-ac-1-empty" className="rounded-lg border border-border bg-card p-12 text-center text-muted-foreground">
            {t('admin.courseDetail.notFound', { defaultValue: 'Course not found.' })}
          </div>
        )}

        {!loading1 && !error1 && course && (
          <div data-testid="adm-03-course-detail-ac-1" className="grid grid-cols-1 gap-6 lg:grid-cols-[2fr_1fr] lg:items-start">
            <div className="space-y-6">
              {/* Course editor */}
              <form data-testid="adm-03-course-detail-ac-2" className={`${CARD} space-y-4`} onSubmit={(e) => e.preventDefault()}>
                <h2 data-testid="adm-03-course-detail-heading" className="text-lg font-semibold text-foreground">
                  {t('admin.courseDetail.course', { defaultValue: 'Course' })}
                </h2>
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <label className="flex flex-col gap-1">
                    <span className={LABEL}>{t('admin.courseDetail.titleField', { defaultValue: 'Title' })}</span>
                    <input name="title" type="text" defaultValue={course.title ?? ''} onChange={(e) => slugField.follow(e.target.value)} className={INPUT} data-testid="adm-03-course-detail-ac-2-title" />
                  </label>
                  <label className="flex flex-col gap-1">
                    <span className={LABEL}>{t('admin.courseDetail.slug', { defaultValue: 'Slug' })}</span>
                    <input name="slug" type="text" value={slugField.value} onChange={slugField.onChange} className={INPUT} data-testid="course-detail-slug" />
                  </label>
                  <label className="flex flex-col gap-1">
                    <span className={LABEL}>{t('admin.courseDetail.category', { defaultValue: 'Category' })}</span>
                    <select name="categoryId" value={categoryId} onChange={(e) => setCategoryId(e.target.value)} className={INPUT} data-testid="course-detail-category">
                      <option value="">{t('admin.courseDetail.selectCategory', { defaultValue: 'Select category' })}</option>
                      {categories.map((c) => (
                        <option key={optId(c) || optName(c)} value={optId(c)}>{optName(c)}</option>
                      ))}
                    </select>
                  </label>
                  <label className="flex flex-col gap-1">
                    <span className={LABEL}>{t('admin.courseDetail.instructor', { defaultValue: 'Instructor' })}</span>
                    <select name="instructorId" value={instructorId} onChange={(e) => setInstructorId(e.target.value)} className={INPUT} data-testid="course-detail-instructor">
                      <option value="">{t('admin.courseDetail.selectInstructor', { defaultValue: 'Select instructor' })}</option>
                      {instructors.map((i) => (
                        <option key={optId(i) || optName(i)} value={optId(i)}>{optName(i)}</option>
                      ))}
                    </select>
                  </label>
                  <label className="flex flex-col gap-1">
                    <span className={LABEL}>{t('admin.courseDetail.price', { defaultValue: 'Price' })}</span>
                    <input name="price" type="number" defaultValue={course.price ?? ''} className={INPUT} data-testid="course-detail-price" />
                  </label>
                  <label className="flex flex-col gap-1">
                    <span className={LABEL}>{t('admin.courseDetail.status', { defaultValue: 'Status' })}</span>
                    <select name="status" defaultValue={String(course.status ?? '')} className={INPUT} data-testid="course-detail-status">
                      {statusOptions.map(([k, v]) => (
                        <option key={k} value={String(v)}>{titleCase(k)}</option>
                      ))}
                    </select>
                  </label>
                </div>
                <ImageUrlField
                  name="thumbnailUrl"
                  label={t('admin.courseDetail.cover', { defaultValue: 'Cover image' })}
                  value={thumbnail}
                  onChange={setThumbnail}
                  hint={t('admin.courseDetail.coverHint', { defaultValue: 'A link to the image. Shown on the course card and the course page.' })}
                  emptyLabel={t('admin.courseDetail.coverEmpty', { defaultValue: 'No image yet' })}
                  invalidLabel={t('admin.courseDetail.coverBroken', { defaultValue: 'That link did not load' })}
                  labelClassName={LABEL}
                  inputClassName={INPUT}
                  testId="course-detail-cover"
                />
                <label className="flex flex-col gap-1">
                  <span className={LABEL}>{t('admin.courseDetail.summary', { defaultValue: 'Summary' })}</span>
                  <textarea name="summary" rows={3} defaultValue={course.summary ?? ''} className={`${INPUT} min-h-[80px]`} data-testid="adm-03-course-detail-ac-2-content" />
                </label>
                <button type="button" onClick={updateCourses2} disabled={loading2} className={BTN_PRIMARY} data-testid="adm-03-course-detail-ac-2-action">
                  {loading2 ? t('admin.courseDetail.saving', { defaultValue: 'Saving…' }) : t('admin.courseDetail.saveCourse', { defaultValue: 'Save course' })}
                </button>
              </form>

              {/* Sections and lessons */}
              <div data-testid="adm-03-course-detail-ac-3" className={`${CARD} space-y-4`}>
                <div className="flex items-center justify-between gap-4">
                  <h2 className="text-lg font-semibold text-foreground">
                    {t('admin.courseDetail.sectionsAndLessons', { defaultValue: 'Sections and lessons' })}
                  </h2>
                  <button type="button" onClick={openAddLesson} className={BTN_SECONDARY} data-testid="adm-03-course-detail-ac-3-action">
                    <Plus className="h-4 w-4" aria-hidden="true" />
                    {t('admin.courseDetail.addLesson', { defaultValue: 'Add lesson' })}
                  </button>
                </div>

                <SearchInput
                  value={lessonQuery}
                  placeholder={t('admin.courseDetail.searchLessons', { defaultValue: 'Search lessons' })}
                  onDebouncedChange={setLessonQuery}
                  testId="lessons-search"
                />

                {sel.count > 0 && (
                  <div data-testid="adm-03-course-detail-ac-4" className="flex flex-wrap items-center justify-between gap-3 rounded-md border border-border bg-muted/40 px-4 py-2">
                    <BulkActions
                      testId="lessons"
                      count={sel.count}
                      onClear={sel.clear}
                      actions={[{ label: t('admin.courseDetail.export', { defaultValue: 'Export' }), onSelect: () => { toast.info(t('admin.courseDetail.exportStarted', { count: sel.count, defaultValue: 'Preparing export…' })); } }]}
                    />
                    <button
                      type="button"
                      onClick={() => removeLessons4()}
                      disabled={loading4 || !isAdmin}
                      className={BTN_DANGER}
                      data-testid="adm-03-course-detail-ac-4-action"
                    >
                      <Trash2 className="h-4 w-4" aria-hidden="true" />
                      {loading4 ? t('admin.courseDetail.deleting', { defaultValue: 'Deleting…' }) : t('admin.courseDetail.delete', { defaultValue: 'Delete' })}
                    </button>
                  </div>
                )}

                <div data-testid="adm-03-course-detail-ac-1-list">
                  <DataTable
                    data={filteredLessons}
                    columns={columns}
                    rowKey={(r) => String(r.id)}
                    rowAction={(row) => (
                      <RowActions
                        testId={`lessons-${row.id}`}
                        onDelete={isAdmin ? () => removeLesson(String(row.id)) : undefined}
                      />
                    )}
                    testId="lessons-table"
                    emptyMessage={t('admin.courseDetail.noLessons', { defaultValue: 'No lessons yet.' })}
                  />
                </div>

                <EntityFormModal
                  open={addOpen}
                  entityLabel={t('admin.courseDetail.lesson', { defaultValue: 'Lesson' })}
                  onClose={() => setAddOpen(false)}
                  onSubmit={handleAddLesson}
                  testId="lessons"
                >
                  <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                    <label className="flex flex-col gap-1">
                      <span className={LABEL}>{t('admin.courseDetail.titleField', { defaultValue: 'Title' })}</span>
                      <input name="title" type="text" required className={INPUT} data-testid="adm-03-course-detail-ac-3-title" />
                    </label>
                    {/* A lesson belongs to a section. This asked for a raw UUID,
                        typed by hand, on a page that never showed one — and a new
                        course has no sections at all, so its first lesson could
                        not be added. Pick one, or name a new one. */}
                    <label className="flex flex-col gap-1">
                      <span className={LABEL}>{t('admin.courseDetail.section', { defaultValue: 'Section' })}</span>
                      <select
                        value={lessonSection}
                        onChange={(e) => setLessonSection(e.target.value)}
                        className={INPUT}
                        data-testid="lessons-field-section"
                      >
                        {sections.map((sec) => (
                          <option key={sec.id} value={sec.id}>{sec.title}</option>
                        ))}
                        <option value={NEW_SECTION}>
                          {t('admin.courseDetail.newSection', { defaultValue: '+ New section…' })}
                        </option>
                      </select>
                    </label>
                    {lessonSection === NEW_SECTION && (
                      <label className="flex flex-col gap-1 sm:col-span-2">
                        <span className={LABEL}>{t('admin.courseDetail.newSectionName', { defaultValue: 'New section name' })}</span>
                        <input
                          name="sectionTitle"
                          type="text"
                          placeholder={t('admin.courseDetail.newSectionHint', { defaultValue: 'e.g. Getting started' })}
                          className={INPUT}
                          data-testid="adm-03-course-detail-ac-3-content"
                        />
                      </label>
                    )}
                    <label className="flex flex-col gap-1">
                      <span className={LABEL}>{t('admin.courseDetail.type', { defaultValue: 'Type' })}</span>
                      <select
                        name="contentType"
                        value={lessonType}
                        onChange={(e) => setLessonType(e.target.value)}
                        className={INPUT}
                        data-testid="lessons-field-type"
                      >
                        {typeOptions.map(([k, v]) => (
                          <option key={k} value={String(v)}>{titleCase(k)}</option>
                        ))}
                      </select>
                      {/* Four words with no explanation is a guess, not a choice. */}
                      <span className="text-[12px] leading-[1.5] text-muted-foreground" data-testid="lessons-field-type-help">
                        {t(`admin.courseDetail.typeHelp.${Number(lessonType)}`, {
                          defaultValue: TYPE_HELP[Number(lessonType)]?.en ?? '',
                        })}
                      </span>
                    </label>
                    <label className="flex flex-col gap-1">
                      <span className={LABEL}>{t('admin.courseDetail.durationMinutes', { defaultValue: 'Duration (minutes)' })}</span>
                      <input name="durationMinutes" type="number" className={INPUT} data-testid="lessons-field-duration" />
                    </label>
                    <label className="flex flex-col gap-1">
                      <span className={LABEL}>{t('admin.courseDetail.order', { defaultValue: 'Order' })}</span>
                      <input name="displayOrder" type="number" className={INPUT} data-testid="lessons-field-order" />
                    </label>
                    {/* The lesson's actual content. The entity has carried `video_url`
                        and `content` since the schema was written and the API accepted
                        both; this form never offered them, so no lesson created here
                        could be watched. A URL, not an upload: a YouTube or Vimeo page
                        link or a direct .mp4 — the player embeds whichever it is given,
                        and no file has to live on this server. */}
                    <label className="flex flex-col gap-1 sm:col-span-2">
                      <span className={LABEL}>{t('admin.courseDetail.videoUrl', { defaultValue: 'Video URL' })}</span>
                      <input
                        name="videoUrl"
                        type="url"
                        inputMode="url"
                        placeholder="https://www.youtube.com/watch?v=… or https://…/lesson.mp4"
                        className={INPUT}
                        data-testid="lessons-field-video-url"
                      />
                      <span className="text-[12px] text-muted-foreground">
                        {t('admin.courseDetail.videoUrlHint', { defaultValue: 'YouTube, Vimeo, or a direct link to an .mp4 / .webm file.' })}
                      </span>
                    </label>
                    {/* Written material, with formatting — a plain textarea meant an
                        article lesson could only ever be one unbroken block of text.
                        The student player renders this HTML. */}
                    <div className="flex flex-col gap-1 sm:col-span-2">
                      <span className={LABEL}>{t('admin.courseDetail.content', { defaultValue: 'Article / notes' })}</span>
                      <RichTextEditor
                        value={lessonContent}
                        onChange={setLessonContent}
                        placeholder={t('admin.courseDetail.contentHint', { defaultValue: 'Shown under the video, or as the lesson itself for an article.' })}
                        testId="lessons-field-content"
                      />
                    </div>
                    {lessonError && (
                      <p className="sm:col-span-2 text-[13px] text-[var(--c-error)]" role="alert" data-testid="lessons-form-error">
                        {lessonError}
                      </p>
                    )}
                  </div>
                </EntityFormModal>
              </div>
            </div>

            {/* At a glance */}
            <aside className={`${CARD} space-y-4 lg:sticky lg:top-6`}>
              <h2 className="text-lg font-semibold text-foreground">
                {t('admin.courseDetail.atAGlance', { defaultValue: 'At a glance' })}
              </h2>
              <div className="flex flex-col gap-1">
                <span className="text-2xl font-bold text-foreground">{studentsCount.toLocaleString()}</span>
                <span className="text-xs text-muted-foreground">{t('admin.courseDetail.students', { defaultValue: 'Students' })}</span>
              </div>
              <div className="flex flex-col gap-1">
                <span className="text-2xl font-bold text-foreground">{ratingValue.toLocaleString()}</span>
                <span className="text-xs text-muted-foreground">{t('admin.courseDetail.rating', { defaultValue: 'Rating' })}</span>
              </div>
              <div className="flex flex-col gap-1">
                <span className="text-2xl font-bold text-foreground">{lessons.length}</span>
                <span className="text-xs text-muted-foreground">{t('admin.courseDetail.lessons', { defaultValue: 'Lessons' })}</span>
              </div>
              <Link to="/admin/enrollments" data-testid="course-detail-enrollments" className={BTN_GHOST}>
                {t('admin.courseDetail.viewEnrollments', { defaultValue: 'View enrollments' })}
              </Link>
            </aside>
          </div>
        )}
      </main>
    </div>
  );
}
